const renderer=new BattleRenderer($('#battle-map'),()=>state,()=>ui);let autoTimer;let saveMessage='',toastTimer,enemyRunning=false;let pendingTransaction=null,shopKind=null,shopMode='buy',shopHero='eric',frontierWalking=false,navigationEpoch=0,walkUntil=0;
