function toast(msg){$('#toast').textContent=msg;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
function save(){const r=saveGame(state,storage);saveMessage=r.ok?'✓ 자동 저장됨':'저장 실패 · 백업 필요';$('#save-status').textContent=saveMessage;$('#save-status').style.color=r.ok?'#a4c4aa':'#edb398';if(!r.ok)toast(`저장 실패: ${r.error}. 메뉴에서 텍스트 백업을 복사하세요.`);return r;}
function commit(){if(!ui.busy)openStory(state);save();render();}
function setScreen(screen){heldMovement.clear();ui.menu=null;ui.pendingMove=null;state.screen=screen;ui.phaseConfirm=false;ui.notice=null;ui.inspected=null;ui.preview=null;ui.mode='choose';commit();}
function portrait(u,cls='portrait'){return `<canvas class="${cls}" width="256" height="256" data-sprite="${u.id}" aria-label="${esc(u.name)}"></canvas>`;}
function paintPortraits(){document.querySelectorAll('[data-sprite]').forEach(canvas=>{const u=findUnit(state,canvas.dataset.sprite)||SPEAKERS[canvas.dataset.sprite];if(!u)return;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.clearRect(0,0,canvas.width,canvas.height);drawPortrait(c,{...u,expression:canvas.dataset.expression||'neutral'});});}
function bar(label,value,max,cls=''){return `<div class="bar-row"><span>${label}</span><div class="meter ${cls}"><b style="width:${max?100*value/max:0}%"></b></div><span>${value}/${max}</span></div>`;}
function heroCards(){return HEROES.map(h=>{const u=findUnit(state,h.id);return `<button class="hero-card ${ui.selected===u.id?'selected':''}" data-do="select" data-id="${u.id}">${portrait(u,'card-sprite')}<h3>${u.name}</h3><p>LV ${u.level} · ${u.role}<br>${u.className}</p></button>`;}).join('');}
function heroDetail(u){return `<div class="hero-detail">${portrait(u)}<div><h3>${u.name} <span class="tag">LV ${u.level}</span></h3><p>${esc(u.description)}</p><p class="accent">${esc(u.talent)} · ${u.skill}</p></div></div>`;}
function render(){
 ensureFrontier(state);audio.select(shopKind&&$('#modal-root').children.length?'shop':musicScene(state));
 const mission=missionOf(state);const battle=state.screen==='battle',deploy=state.screen==='deployment',u=findUnit(state,ui.selected);const rescued=state.units.filter(c=>c.rescued).length,boss=findUnit(state,'boss');
 $('#phasebar').innerHTML=`<span class="eyebrow">MISSION ${String(state.missionId).padStart(2,'0')}</span><span class="turn">${battle||state.screen==='result'?`TURN ${String(state.turn).padStart(2,'0')}`:mission.en}</span><span class="phase-pill">${deploy?'FREE DEPLOYMENT':battle?`${state.phase.toUpperCase()} PHASE`:state.screen==='result'?state.outcome.toUpperCase():'CAMPAIGN'}</span><div class="objectives"><span class="objective">${esc(mission.objective)}</span><span class="objective">${state.missionId===2?`대장 HP ${boss.hp}/${boss.maxHP}`:`구조 ${rescued}/${mission.civilians.length}`}${state.missionId===3?` · 철수 ${state.units.filter(u=>u.team==='ally'&&alive(u)&&u.y<=2).length}/${state.units.filter(u=>u.team==='ally'&&alive(u)).length} · ${Math.max(0,11-state.turn)}턴 남음`:''}${state.practice?' · 연습 (성장 비확정)':''}</span></div>`;
 $('#map-label').innerHTML=battle||deploy?`<div class="eyebrow">BORDERLANDS · SOUTHERN APPROACH</div><h3>${mission.en}</h3><p>${deploy?'남쪽의 푸른 영역에 장수를 자유 배치하세요.':mission.brief}</p>`:'';
 $('#board-caption').textContent=battle?ui.busy?'적의 행동을 지켜보세요.':ui.preview?'예측을 확인한 뒤 행동을 확정하세요.':!u||u.acted?'다음 장수를 선택하거나 Phase를 종료하세요.':ui.mode==='move'?`${u.name} · 푸른 칸으로 이동. 이동 후에는 취소할 수 있습니다.`:ui.mode==='rescue'?'인접한 주민을 선택하세요.':ui.mode==='skill'?`${u.skill} · 유효한 대상을 선택하세요.`:'붉은 범위의 적을 선택해 공격을 예측하세요.':deploy?'장수 선택 → 남쪽 Tile 클릭 · 다른 장수 위치를 클릭하면 Swap':'';
 $('#logentries').innerHTML=state.log.slice(-18).map(l=>`<div>${esc(l)}</div>`).join('');$('#logentries').scrollTop=$('#logentries').scrollHeight;
 renderObjectives();$('#battle-minimap').hidden=!(battle||deploy);app.classList.toggle('exploring',state.screen==='exploration');app.classList.toggle('in-battle',battle||deploy);app.classList.toggle('journal-open',ui.journal);$('#rail').hidden=!(battle||deploy);$('#screen').innerHTML='';
 if(battle||deploy){$('#rail').innerHTML=renderDock(state,ui,esc,portrait,(label,value,max,cls)=>bar(label,label==='HP'?renderer.displayHP(u):value,max,cls));}else{renderScreen();$('#rail').innerHTML=`<div class="eyebrow">COMMANDER’S NOTES</div><h3 style="margin:13px 0">한 사람씩, 하나의 가능성</h3><p style="font-size:13px">다섯 장수의 역할을 연결하세요. 숲의 사수, 동료를 지키는 기사, 빠른 구출과 치유가 전장의 흐름을 바꿉니다.</p><div class="rule"></div><div class="eyebrow">MISSION OBJECTIVES</div><p style="font-size:12px;margin:10px 0">주민 2명 구출 + Garr 격파<br>선택 목표: 전원 생존 · 8턴 이내 · Eric의 단서</p><div class="rule"></div><div class="muted">완료한 미션: ${state.campaign.clears}회<br>v${VERSION} · 오리지널 픽셀 아트<br>오프라인 실행 · 로컬 저장</div><button class="small" data-do="help" style="margin-top:18px">조작과 전투 규칙</button>`;}
 const pop=$('#unit-popover');pop.innerHTML=menuHTML(state,ui,esc);pop.hidden=!pop.innerHTML;positionPopover();renderStory();paintPortraits();const hubCanvas=$('#frontier-map');if(hubCanvas){drawHub(hubCanvas,state);followAren();}const stage=$('#scene-stage');if(stage)drawHub(stage,state,{line:storyLine(state)});offerAffiliation();
}
function positionPopover(){
 const pop=$('#unit-popover');if(!pop||pop.hidden)return;const selected=findUnit(state,ui.selected),unit=findUnit(state,ui.preview||ui.selected),anchor=ui.pendingMove||unit;if(!anchor)return;
 const center=renderer.tileCenter(anchor.x,anchor.y),field=$('.field'),protectedPoints=state.units.filter(t=>alive(t)&&(t.id===selected?.id||ui.menu==='root'&&canAct(state,selected)&&(t.team==='ally'||validTarget(state,selected,t,'attack')||validTarget(state,selected,t,'skill')||validTarget(state,selected,t,'rescue')||t.team==='enemy'&&Math.abs(selected.x-t.x)+Math.abs(selected.y-t.y)<=Math.max(selected.range[1],rangeFor(selected,'skill')[1])))).map(t=>({...renderer.tileCenter(t.x,t.y),radius:Math.max(6,renderer.camera.scale*32),weight:t.id===selected?.id?1:t.team==='ally'?4:100}));
 if(ui.menu==='root'&&canAct(state,selected)&&!selected.moved)for(const key of movement(state,selected).costs.keys()){const [x,y]=key.split(',').map(Number);protectedPoints.push({...renderer.tileCenter(x,y),radius:renderer.camera.scale*18,weight:20});}
 const pos=placePopover({width:field.clientWidth,height:field.clientHeight,popupWidth:pop.offsetWidth,popupHeight:pop.offsetHeight,anchor:center,protectedPoints}),left=pos.x+'px',top=pos.y+'px';if(pop.style.left!==left)pop.style.left=left;if(pop.style.top!==top)pop.style.top=top;
}
renderer.onCamera=()=>{positionPopover();const u=findUnit(state,ui.selected),hp=$('.dock-vitals .bar-row');if(u&&hp){const shown=renderer.displayHP(u),value=hp.lastElementChild,meter=hp.querySelector('.meter b');if(value.textContent!==`${shown}/${u.maxHP}`){value.textContent=`${shown}/${u.maxHP}`;meter.style.width=100*shown/u.maxHP+'%';}}};
async function previewMove(id,x,y){const u=findUnit(state,id),path=pathTo(state,u,x,y);if(!canAct(state,u)||u.moved||!path||path.length<2)return false;ui.pendingMove={id,x,y,path};renderer.focus(x,y);ui.menu=null;ui.preview=null;ui.notice='이동 경로를 따라 걷는 중입니다. 도착 후 확정하거나 취소하세요.';ui.busy=true;render();const duration=renderer.walk(id,path,ui.movement,ui.speed);await new Promise(r=>setTimeout(r,duration+24));ui.busy=false;ui.menu='move-confirm';ui.notice=null;render();return true;}
async function cancelMovement(){const m=ui.pendingMove;if(!m)return;ui.menu=null;ui.busy=true;render();const duration=renderer.walk(m.id,[...m.path].reverse(),ui.movement,ui.speed);await new Promise(r=>setTimeout(r,duration+24));renderer.motion.delete(m.id);ui.pendingMove=null;ui.busy=false;const original=findUnit(state,m.id);renderer.focus(original.x,original.y);ui.mode='move';ui.menu='root';ui.notice='이동 취소 · 원래 위치와 이동권을 유지합니다.';render();}
function confirmMovement(){const m=ui.pendingMove;if(!m)return;const path=moveUnit(state,m.id,m.x,m.y);renderer.motion.delete(m.id);ui.pendingMove=null;ui.menu='root';ui.mode='choose';ui.notice=path?'이동 확정 · 공격, 스킬, 도구 또는 대기를 선택하세요.':'이동을 확정할 수 없습니다. 원래 위치를 유지합니다.';commit();}
function renderVictoryRewards(last){if(state.outcome!=='victory')return '';const r=last.rewards;if(state.practice||last.practice)return '<section class="victory-rewards"><h3>Practice · 보상 미확정</h3><p>정식 Gold / Inventory는 증가하지 않습니다.</p></section>';return `<section class="victory-rewards"><h3>Victory Rewards</h3><p>${r?`${r.gold} Gold · ${r.extras.map(rewardLabel).join(' / ')}`:'이전 버전 클리어 · 신규 보상은 Inventory에 반영됩니다.'}</p><p>Optional: ${state.missionId===2?(state.campaign.flags.mission_02_prisoner_captured?'생포 달성':'생포 미달성'):`주민 ${last.rescued}/${missionOf(state).civilians.length} 구조`}</p>${state.economy.rewardPending.length?'<p>소지 한도 초과 보상은 보관됩니다. 준비 화면 Inventory에서 받으세요.</p>':''}<p>Relationship: ${state.campaign.bonds.erik_kai?'Erik / Kai 협력 기록':'동료 관계와 Potential 기록은 아래 성장 결과에서 확인하세요.'}</p></section>`;}
function renderScreen(){const u=findUnit(state,ui.selected);let html='';
 if(state.screen==='exploration'){$('#screen').innerHTML=renderFrontier(state,esc);$('#phasebar').innerHTML=`<span class="eyebrow">EXPLORATION</span><span class="turn">${HUBS[state.frontier.hub].name}</span><span class="phase-pill">${state.frontier.phase.toUpperCase()}</span>`;return;}
 if(state.screen==='title')html=`<div class="title-inner"><div class="eyebrow">AN ORIGINAL FANTASY TACTICAL RPG</div><h1>Ashen<br>Crown<span class="accent">.</span></h1><div class="subtitle">ACT I — The Living Frontier</div><p>재가 된 왕관 아래, 다섯 동료의 이야기가 시작됩니다.<br>당신의 선택은 전장을 바꾸고, 장수의 숨겨진 가능성을 깨웁니다.</p><div class="title-actions"><button class="primary" data-do="new">캠페인 시작 →</button><button data-do="load" ${loaded.state||state.campaign.clears?'':'disabled'}>저장 불러오기</button><button data-do="campaign">Campaign</button><button data-do="audio">♫ Music</button><button data-do="help">플레이 안내</button></div><div class="title-bottom"><div>TACTICAL COMBAT<br><span class="accent">지형 · 사거리 · 협공</span></div><div>CHARACTER GROWTH<br><span class="accent">다섯 장수 · 서로 다른 역할</span></div><div>HIDDEN POTENTIAL<br><span class="accent">행동에서 발견하는 단서</span></div></div></div>`;
 else if(state.screen==='intro')html=`<div class="screen-inner"><div class="eyebrow">ACT I · MISSION ${state.missionId}</div><h2>${missionOf(state).title}</h2><div class="story">${esc(missionOf(state).objective)}<br><br>${esc(missionOf(state).brief)}<br><br>아렌의 명령 아래, 다섯 동료가 각자의 이유로 전장에 나섭니다.</div><button class="primary" data-do="warroom">동료들과 전투 준비 →</button></div>`;
 else if(state.screen==='warroom')html=`<div class="screen-inner council-screen">${councilHTML(state,esc,portrait,ui.selected)}</div>`;
 else if(state.screen==='result'){
 const victory=state.outcome==='victory',last=state.campaign.results.at(-1);
 html=`<div class="screen-inner"><div class="eyebrow">MISSION ${state.missionId} · GROWTH JOURNAL</div><div class="result-head"><h2>${victory?'Mission Complete':'A Costly Lesson'}</h2><span class="muted">TURN ${state.turn}<br>${victory?'VICTORY':'DEFEAT'} · 구조 ${last.rescued}/${missionOf(state).civilians.length}</span></div><p style="font-size:13px;margin-top:12px">${esc(state.reason)}</p>${renderVictoryRewards(last)}<div class="badges"><span class="badge ${last.allAlive?'':'failed'}">${last.allAlive?'✓':'◇'} 전원 생존</span><span class="badge ${last.swift&&victory?'':'failed'}">${last.swift&&victory?'✓':'◇'} ${missionOf(state).par}턴 이내 승리</span><span class="badge ${last.potential?'':'failed'}">${last.potential?'✓':'◇'} Guardian’s Oath 단서</span></div><div class="growth-list">${HEROES.map(h=>{const a=findUnit(state,h.id),start=state.missionStart.find(m=>m.id===a.id);const gains=a.growthHistory.filter(g=>g.level>start.level);return `<article class="growth-card" data-growth="${a.id}"><div class="row"><h3>${a.name}</h3><span class="gain">+${a.earnedXP} EXP · LV ${start.level} → ${a.level}</span></div><p>${gains.length?`성장: HP +${a.maxHP-start.stats.maxHP} · ATK +${a.atk-start.stats.atk} · DEF +${a.def-start.stats.def} · MAG +${a.mag-start.stats.mag}`:'이번 전투의 경험이 다음 성장을 준비합니다.'}</p><p>${esc([...new Set(a.highlights)].slice(-3).join(' · ')||'동료와 함께 첫 전장을 경험했습니다.')}${a.hp===0?' · 전투불능':''}</p><p class="accent">${a.clues.length?`Potential: ${esc(a.clues.join(', '))} (1/3)`:'숨겨진 잠재력은 아직 발견되지 않았습니다.'}</p><p class="goal">다음 성장 목표 · ${esc(h.goal)}</p></article>`;}).join('')}</div><div class="row">${victory&&state.missionId<3&&state.campaign.completed.includes(state.missionId)?`<button class="primary" data-do="next-mission" ${ui.busy?'disabled':''}>Mission ${state.missionId+1} →</button>`:''}<button class="primary" data-do="aftermath">${victory?'마을 / 야영지로 돌아가기':'야영지에서 다시 준비'} →</button><button data-do="replay" ${ui.busy?'disabled':''}>${victory?'현재 Mission 연습':'전투 전 성장으로 재도전'} →</button><button data-do="fresh-replay" ${ui.busy?'disabled':''}>LV 초기 상태로 연습</button><button data-do="backup" ${ui.busy?'disabled':''}>텍스트 백업</button></div><p class="muted" style="margin-top:13px">${ui.busy?'전투 결과를 정리하고 있습니다. 잠시 후 재도전할 수 있습니다.':victory?'성장한 장수와 결과가 저장되었습니다.':'패배 기록을 저장했습니다. 재도전은 이번 전투 시작 전 성장 상태로 돌아갑니다.'} ${state.missionId===3?'ACT I 전반 완료 · 다음은 버려진 성채 (v0.4 예정).':'첫 클리어 성장만 확정합니다. 재플레이의 EXP는 연습용입니다.'}</p></div>`;
 }
 $('#screen').innerHTML=`<div class="screen-overlay ${state.screen==='result'?'result-overlay':''}">${html}</div>`;
}
function modal(title,body,actions){heldMovement.clear();$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-title"><h2>${esc(title)}</h2><button class="modal-close" data-do="close-modal" aria-label="닫기">×</button></div>${body}<div class="row">${actions}</div></section></div>`;const dialog=$('#modal-root .modal');dialog.tabIndex=-1;dialog.focus({preventScroll:true});dialog.scrollTop=0;}
function closeModal(){if($('#modal-root .modal')?.getAttribute('aria-label')==='동료의 약속'){state.frontier.pendingRecruit=null;syncFrontier(state);save();}pendingTransaction=null;shopKind=null;$('#modal-root').innerHTML='';audio.select(musicScene(state));if(state.narrative.active){renderStory();paintPortraits();}$('#battle-map').focus({preventScroll:true});}
const help=()=>modal('전투 안내',`<p><b>목표:</b> 주민 2명 구출 + 산적 대장 Garr 격파. 주민 한 명이라도 사망하거나 아군이 전멸하면 패배합니다.</p><p><b>조작:</b> 장수 탭 → 작은 행동 메뉴 → 이동 → 목적지 → 이동 확정. 이후 공격/스킬 → 대상 → 예측 → 행동 확정. 유닛당 이동 1회와 행동 1회. 공격·스킬·구출·약·대기는 행동을 마칩니다. 행동 전 이동은 Z로 취소할 수 있습니다.</p><p><b>지형:</b> Grass / Road 이동 비용 1. Forest 비용 2, DEF +1 / 회피 +12%; Kai는 숲 비용 1. Village DEF +2. Ruin은 통과 불가. 사거리는 직교 거리입니다. 건물이나 숲이 사격을 차단하지 않습니다.</p><p><b>스킬:</b> Guard는 인접 동료를 보호하며, Eric이 그 동료 옆에 있을 때 첫 인접 근접 피해를 대신 받습니다. Fire Bolt는 RES를 적용합니다. Heal은 자기 회복 가능. Quick Strike의 협공은 적 반대편 인접 아군이 있어야 성립합니다.</p><p><b>이벤트:</b> TURN 3 증원, TURN 5 주민 공격 시작. 주민 옆에서 구출 행동. 마법에도 기본 공격 사거리 내에서는 반격 가능. 반격에 대한 재반격은 없습니다.</p><p><b>키:</b> 1 이동 · 2 공격 · 3 스킬 · 4 구출 · Z 취소 · W 대기 · Tab 다음 장수 · E Phase 종료 · Escape 취소. 휠 Zoom, 우클릭/Shift 드래그 Pan. Touch는 탭과 드래그 Pan 지원. 선택한 장수의 얼굴과 HP/MP는 하단에 표시됩니다. 작은 메뉴에서 스킬·도구·특성을 열 수 있습니다. 하단에서 칸별 걷기 / 연속 걷기 / 즉시 이동, 속도와 약한 효과를 선택하세요. 두 손가락으로 확대할 수 있습니다. 이동을 선택한 뒤 같은 Tile을 누르면 제자리에서 행동합니다.</p><p>로컬 저장은 현재 브라우저와 파일 경로에 연결됩니다. 파일을 옮기거나 다른 브라우저를 사용하기 전 텍스트 백업을 권장합니다. 초기화는 메뉴에서 직접 확인합니다.</p>`,'');
function nextHero(){const ids=HEROES.map(h=>h.id),start=ids.indexOf(ui.selected);for(let i=1;i<=5;i++){const u=findUnit(state,ids[(start+i)%5]);if(canAct(state,u)){ui.selected=u.id;renderer.focus(u.x,u.y);ui.mode=u.moved?'choose':'move';ui.menu='root';ui.preview=null;ui.notice=null;ui.inspected=null;render();return;}}ui.preview=null;render();}
async function effects(before){for(const e of state.feedback)if(['attack','heal','death'].includes(e.type))audio.effect(e.type);if(state.outcome&&!before.outcome)audio.stinger(state.outcome);
 const duration=renderer.addEffects(state.feedback,before,{movement:ui.movement,speed:ui.speed,reduced:ui.reduced});const potential=state.feedback.find(e=>e.type==='potential');if(potential){const u=findUnit(state,potential.id);toast(`${u.name} · Potential Clue Discovered — ${u.clues.at(-1)} (1/3)`);}await new Promise(r=>setTimeout(r,duration+24));}
async function startEnemyPhaseUI(){const before=structuredClone(state);if(!beginEnemyPhase(state))return;ui.busy=true;const playing=effects(before);save();render();await playing;ui.busy=false;await enemyLoop();}
async function enemyLoop(){if(enemyRunning)return;ui.menu=null;enemyRunning=true;ui.busy=true;render();try{while(state.phase==='enemy'&&state.screen==='battle'&&!state.narrative.active){const before=structuredClone(state);advanceEnemy(state);const actor=findUnit(state,state.feedback.find(e=>e.type==='move'||e.type==='attack')?.id);if(actor)renderer.focus(actor.x,actor.y);const playing=effects(before);const stored=save();if(!stored.ok&&state.outcome==='victory'&&!before.outcome){state=before;renderer.clearPresentation();toast('승리 보상을 저장하지 못했습니다. 이전 행동으로 돌아갑니다.');break;}render();await playing;}ui.preview=null;if(!canAct(state,findUnit(state,ui.selected)))ui.selected=HEROES.find(h=>alive(findUnit(state,h.id)))?.id||'eric';ui.mode='choose';const selected=findUnit(state,ui.selected);if(selected)renderer.focus(selected.x,selected.y);}finally{ui.busy=false;enemyRunning=false;commit();}}
async function execute(mode,target){if(ui.busy)return;const before=structuredClone(state);const r=performAction(state,ui.selected,mode,target);if(!r.ok){toast(r.error);return;}ui.preview=null;ui.menu=null;ui.notice=null;ui.inspected=null;ui.phaseConfirm=false;ui.busy=true;const playing=effects(before);const stored=save();if(!stored.ok&&state.outcome==='victory'&&!before.outcome){state=before;renderer.clearPresentation();ui.busy=false;render();toast('승리 보상을 저장하지 못했습니다. 이전 행동으로 돌아갑니다.');return;}render();await playing;ui.busy=false;if(state.screen==='battle')nextHero();commit();}
async function dispatch(action,id){if(state.narrative.active&&!['story-next','story-skip','story-auto','story-fast','story-log','audio','close-modal','save','menu','backup','copy-backup','restore','load','restart-stage','confirm-restart-stage'].includes(action))return;
if(ui.pendingMove&&!['confirm-move','cancel-move','close-unit-menu','zoom-in','zoom-out','reset-camera','help','close-modal'].includes(action)){ui.menu='move-confirm';render();toast('먼저 이동을 확정하거나 취소하세요.');return;}if(ui.busy&&!['journal','zoom-in','zoom-out','reset-camera','help','close-modal'].includes(action))return;
 if(await frontierDispatch(action,id))return;
 switch(action){
 case 'story-next':case 'story-skip':advanceStory(state,action==='story-skip');commit();if(!state.narrative.active&&state.phase==='enemy'&&state.screen==='battle')enemyLoop();break;
 case 'story-fast':state.narrative.fast=!state.narrative.fast;commit();break;
 case 'story-auto':state.narrative.auto=!state.narrative.auto;commit();break;
 case 'story-log':modal('Dialogue History',`<div class="history">${state.narrative.history.map(l=>`<p><b>${esc(SPEAKERS[l.speaker]?.name||'Enemy')}</b> · ${esc(l.text)}</p>`).join('')||'<p>아직 기록이 없습니다.</p>'}</div>`,'');break;
 case 'audio':showAudio();break;
 case 'campaign':showCampaign();break;
 case 'choose-mission':{if(['battle','deployment'].includes(state.screen)){toast('현재 전투/배치를 마친 뒤 Campaign을 선택하세요.');break;}if(state.outcome==='defeat')state=replay(state);const idn=Number(id);if(!MISSIONS[idn])break;if(idn>1&&!state.campaign.completed.includes(idn-1))break;state=newGame(state.initialSeed,state.campaign,idn);ui.selected='eric';closeModal();enterHub(state);renderer.clearPresentation();renderer.reset();commit();break;}
 case 'appearance':showAppearance();break;
 case 'new':state=newGame(state.initialSeed,state.campaign,state.campaign.completed.includes(1)?Math.min(3,(state.campaign.completed.at(-1)||0)+1):1);ui.selected='eric';enterHub(state);commit();break;
 case 'warroom':await prepareCouncil();break;case 'deploy':state.frontier.ready.formation=true;syncFrontier(state);setScreen('deployment');break;
 case 'select':{const u=findUnit(state,id);if(!u||u.team!=='ally'||state.screen==='battle'&&!alive(u))break;ui.selected=id;ui.menu=state.screen==='battle'?'root':null;ui.mode=state.screen==='battle'&&!u.moved&&!u.acted?'move':initialMode(u);renderer.focus(u.x,u.y);ui.preview=null;ui.notice=null;ui.inspected=null;ui.phaseConfirm=false;render();break;}
 case 'preset':presetDeployment(state,id);commit();break;
 case 'start-battle':if(state.screen==='deployment'){modal('출전 최종 확인',`<p><b>${esc(missionOf(state).objective)}</b></p><p>${esc(councilInfo(state).plan)}</p><p>Equipment / Items / Formation / Objective<br>기본 장비로 출전 가능 · 구매 준비는 선택입니다.</p><p>기본 회복약 2개 + 구매 도구 ${itemCount(state.economy)}개. 출전 이후 장비 변경은 잠깁니다.</p>`,'<button class="primary" data-do="confirm-battle">출전 확정</button><button data-do="close-modal">계속 준비</button>');}break;
 case 'confirm-battle':if(startBattle(state)){closeModal();ui.mode='choose';ui.notice=null;commit();}break;
 case 'open-unit-menu':ui.menu=ui.pendingMove?'move-confirm':'root';render();break;
 case 'submenu':ui.menu=id;render();break;
 case 'close-unit-menu':if(ui.pendingMove)await cancelMovement();else{ui.menu=null;ui.preview=null;render();}break;
 case 'cancel-target':ui.menu=null;ui.preview=null;render();break;
 case 'confirm-move':confirmMovement();break;
 case 'cancel-move':await cancelMovement();break;
 case 'mode':if(canAct(state,findUnit(state,ui.selected))||state.screen==='deployment'){ui.mode=id;ui.menu=null;ui.preview=null;ui.notice=null;ui.inspected=null;ui.phaseConfirm=false;render();}break;
 case 'undo':if(undoMove(state,ui.selected)){ui.menu='root';ui.mode='choose';ui.preview=null;commit();}break;
 case 'wait':await execute('wait');break;case 'item':await execute('item');break;
 case 'confirm':if(ui.preview)await execute(ui.mode,ui.preview);break;
 case 'cancel':if(ui.pendingMove){await cancelMovement();break;}ui.menu=null;ui.preview=null;ui.mode='choose';ui.notice=null;ui.inspected=null;ui.phaseConfirm=false;render();break;
 case 'next':nextHero();break;
 case 'end-phase':{ui.menu=null;const n=state.units.filter(u=>canAct(state,u)).length;if(n){ui.phaseConfirm=true;ui.preview=null;render();}else await startEnemyPhaseUI();break;}
 case 'confirm-phase':ui.menu=null;ui.phaseConfirm=false;await startEnemyPhaseUI();break;
 case 'next-mission':{const next=state.frontier.phase==='aftermath'&&state.missionId<3?newGame(state.initialSeed+1,state.campaign,state.missionId+1):nextMission(state);if(next){state=next;ui.selected='eric';ui.menu=null;ui.preview=null;enterHub(state);renderer.clearPresentation();renderer.reset();commit();}break;}
 case 'replay':case 'fresh-replay':ui.menu=null;ui.pendingMove=null;state=replay(state,action==='fresh-replay');enterHub(state);ui.selected='eric';ui.mode='choose';ui.preview=null;renderer.reset();commit();break;
 case 'save':if(save().ok)toast('전투·성장·RNG 상태를 저장했습니다.');break;
 case 'load':{const r=loadGame(storage);if(r.state){ui.menu=null;ui.pendingMove=null;state=r.state;ui.phaseConfirm=false;ui.notice=null;ui.inspected=null;ui.preview=null;ui.mode='choose';ui.selected='eric';closeModal();render();if(r.warning)toast(r.warning);if(state.phase==='enemy'&&state.screen==='battle')enemyLoop();}else toast(r.warning||'저장이 없습니다.');break;}
 case 'restart-stage':if(['battle','result'].includes(state.screen))modal('스테이지를 초기화할까요?',state.stageStart?'<p>이번 스테이지에서 얻은 경험치·성장·구출·전투 결과를 되돌리고 TURN 1부터 다시 시작합니다. 전투 시작 전 성장, 출전 배치와 이전 스테이지 기록은 유지됩니다.</p>':'<p>이전 저장에는 시작 시점 배치 기록이 없습니다. 영구 성장과 이전 결과를 유지하고 추천 배치 화면부터 다시 준비합니다. 이번 전투 중 아직 확정되지 않은 성장은 되돌립니다.</p>','<button class="danger" data-do="confirm-restart-stage">스테이지 초기화</button>');break;
 case 'confirm-restart-stage':{const initial=restartStage(state);if(initial){state=initial;ui.selected='eric';ui.mode='choose';ui.preview=null;ui.menu=null;ui.pendingMove=null;ui.phaseConfirm=false;ui.inspected=null;ui.notice=null;renderer.clearPresentation();renderer.reset();closeModal();const saved=save();render();if(saved.ok)toast(state.screen==='battle'?'스테이지 초기화 완료 · 시작 배치에서 TURN 1로 돌아왔습니다.':'이전 저장 · 추천 배치에서 다시 출전하세요.');}break;}
 case 'menu':modal('Command Menu','<p>전투는 자동 저장됩니다. 텍스트 백업은 다른 파일 경로와 브라우저에서도 복원할 수 있습니다.</p>',`${state.screen==='exploration'?'<button data-do="inventory">장비 / Party</button><button data-do="items">도구</button>':''}${['warroom','deployment'].includes(state.screen)?'<button data-do="hub-return">탐색으로 돌아가기</button>':''}${['battle','result'].includes(state.screen)?'<button data-do="restart-stage">스테이지 초기화</button>':''}<button data-do="load">저장 불러오기</button><button data-do="backup">백업 / 복원</button><button data-do="campaign">Campaign</button><button data-do="story-log">대화 기록</button><button data-do="audio">음악 / 효과음</button><button data-do="appearance">장수 외형</button><button data-do="help">플레이 안내</button><button class="danger" data-do="reset">전체 저장 초기화</button>`);break;
 case 'backup':modal('텍스트 백업 / 복원','<p>아래 텍스트를 복사해 보관하세요. 복원하려면 저장 텍스트를 붙여넣고 검증 후 복원을 누릅니다.</p><textarea id="backup-text" aria-label="저장 백업 텍스트"></textarea>','<button data-do="copy-backup">전체 선택 / 복사</button><button class="primary" data-do="restore">검증 후 복원</button>');$('#backup-text').value=serialize(state);break;
 case 'copy-backup':$('#backup-text').select();try{await navigator.clipboard.writeText($('#backup-text').value);toast('백업 텍스트를 복사했습니다.');}catch{toast('전체 선택했습니다. Ctrl+C 또는 길게 눌러 복사하세요.');}break;
 case 'restore':try{const restored=deserialize($('#backup-text').value);ui.menu=null;ui.pendingMove=null;state=restored;ui.phaseConfirm=false;ui.notice=null;ui.inspected=null;ui.selected='eric';ui.preview=null;closeModal();commit();toast('검증한 저장을 복원했습니다.');if(state.phase==='enemy'&&state.screen==='battle')enemyLoop();}catch(e){toast(`복원 실패: ${e.message}. 현재 진행 상태를 유지합니다.`);}break;
 case 'reset':modal('모든 저장을 초기화할까요?','<p>장수 성장, 전투와 결과 기록을 삭제합니다. 먼저 텍스트 백업을 보관할 수 있습니다.</p>','<button data-do="backup">먼저 백업</button><button class="danger" data-do="confirm-reset">모든 저장 삭제</button>');break;
 case 'confirm-reset':{const r=resetSave(storage);if(!r.ok){toast(`초기화 실패: ${r.error}`);break;}state=newGame();ui.selected='eric';ui.preview=null;closeModal();render();toast('저장을 초기화했습니다.');break;}
 case 'help':help();break;case 'close-modal':closeModal();break;
 case 'journal':ui.journal=!ui.journal;app.classList.toggle('journal-open',ui.journal);break;
 case 'focus-unit':{const unit=findUnit(state,ui.selected);if(unit)renderer.focus(unit.x,unit.y);break;}
 case 'zoom-in':renderer.zoomBy(1.15);break;case 'zoom-out':renderer.zoomBy(1/1.15);break;case 'reset-camera':renderer.reset();break;
 }
}
// A menu inserted on map pointerup must not receive the same gesture's click.
let pressedCommand=null;
document.addEventListener('pointerdown',e=>{pressedCommand=e.target.closest('[data-do]');if(pressedCommand&&pressedCommand.dataset.do!=='walk'){heldMovement.clear();navigationEpoch++;}audio.activate();},{capture:true});
document.addEventListener('click',e=>{const b=e.target.closest('[data-do]'),pointerClick=!!e.pointerType||!!e.sourceCapabilities?.firesTouchEvents||e.detail>0;if(b&&!b.disabled&&!(b.dataset.do==='walk'&&pointerClick)&&(!pointerClick||pressedCommand===b))dispatch(b.dataset.do,b.dataset.id);});
