function renderStory(){clearTimeout(autoTimer);const l=storyLine(state),n=state.narrative;if(!l){$('#story-root').innerHTML='';return;}ui.menu=null;$('#unit-popover').hidden=true;const staged=l.stage&&!n.active.key.startsWith('npc:');const speaker=findUnit(state,l.speaker)||SPEAKERS[l.speaker]||{id:'boss',name:'Enemy'};$('#story-root').innerHTML=`<section class="dialogue-backdrop ${staged?'staged-scene':'in-place-dialogue'}" role="dialog" aria-modal="true" aria-label="스토리 대화">${staged?'<canvas id="scene-stage" width="1024" height="768" aria-label="인물들이 대화하는 장면"></canvas>':''}<div class="dialogue-panel ${ui.reduced?'reduced':''}" data-expression="${l.expression}"><div class="dialogue-face">${portrait(speaker,'story-portrait')}</div><div class="dialogue-copy"><div class="eyebrow">ACT I · MISSION ${state.missionId} · ${esc(missionOf(state).en)}</div><h3>${esc(speaker.ko||speaker.name)} <small>${esc(speaker.name)}</small></h3><p class="dialogue-text">${esc(l.text)}</p><div class="dialogue-tools"><button class="primary" data-do="story-next">다음 →</button><button data-do="story-auto">${n.auto?'수동':'자동'}</button><button data-do="story-skip" ${n.seen.includes(n.active.key)?'':'disabled'}>본 대화 Skip</button><button data-do="story-fast">${n.fast?'1×':'2× 빠르게'}</button><button data-do="story-log">기록</button><button data-do="audio">♫</button></div><small class="muted">${n.active.index+1} / ${STORY[n.active.key].length} · ${n.seen.includes(n.active.key)?'✓ 이전에 본 장면':'새로운 장면'} · 대화 중에는 이동할 수 없습니다.</small></div></div></section>`;const face=$('#story-root [data-sprite]');if(face)face.dataset.expression=l.expression;if(n.auto)autoTimer=setTimeout(()=>{if(!$('#modal-root').children.length)dispatch('story-next');},Math.max(n.fast?900:2600,l.text.length*(n.fast?25:75)));}
function STORY_LENGTH(key){return key.endsWith('intro')?state.missionId===1?6:4:state.missionId===3&&key.endsWith('end')?4:key.endsWith('capture')?4:key.endsWith('bond')?4:key.endsWith('end')?3:key.endsWith('boss')?3:key==='defeat'?1:2;}
